CREATE DATABASE IF NOT EXISTS snack_inventory CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci; USE snack_inventory;
CREATE TABLE IF NOT EXISTS users(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,username VARCHAR(50) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,role ENUM("owner","admin") NOT NULL DEFAULT "admin",created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS categories(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,description TEXT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS products(id INT AUTO_INCREMENT PRIMARY KEY,category_id INT NULL,code VARCHAR(50) NOT NULL UNIQUE,name VARCHAR(150) NOT NULL,unit VARCHAR(30) NOT NULL,minimum_stock INT NOT NULL DEFAULT 0,stock INT NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE SET NULL ON UPDATE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS stock_movements(id INT AUTO_INCREMENT PRIMARY KEY,product_id INT NOT NULL,type ENUM("IN","OUT") NOT NULL,quantity INT NOT NULL,description VARCHAR(255) NULL,user_id INT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE ON UPDATE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL ON UPDATE CASCADE) ENGINE=InnoDB;
INSERT INTO users(name,username,password,role) VALUES("Administrator","admin",'$2y$10$7EqJtq98hPqEX7fNZaFWoO5Xv6t6Vf7k3h7h1XK4n8K1Q1bY6j1mG',"admin") ON DUPLICATE KEY UPDATE username=username;
